      "passage": null,
      "clusterId": null,
      "question": "Trí tuệ cảm xúc là khả năng nhận dạng cảm xúc, hiểu được ý nghĩa của chúng và nhận ra tác động của chúng đối với những người xung quanh. Trí tuệ cảm xúc bao hàm cả việc nhận thức người khác: khi bạn hiểu cảm xúc của mọi người, bạn sẽ kiểm soát các mối quan hệ hiệu quả hơn. Những người giàu trí tuệ cảm xúc hiểu rõ cảm xúc của mình nên không bao giờ để chúng chế ngự. Đồng thời, họ cũng rất nghiêm khắc khi đánh giá bản thân. Họ biết đâu là điểm mạnh và điểm yếu của mình để từ đó phát huy hoặc khắc phục. Nhờ vậy, họ có thể làm việc hiệu quả hơn. Nhiều người tin rằng sự hiểu rõ bản thân chính là thành tố quan trọng nhất của trí tuệ cảm xúc. . . ( Trí tuệ cảm xúc – yếu tố quan trọng để thành công, Theo mindtools.com) Mục đích chính của đoạn trích là gì?",
