      "sectionName": "Sử dụng Tiếng Việt (300đ)",
      "passage": "Dựa vào thông tin dưới đây để trả lời các câu từ 21 đến 25:\nĐem đại nghĩa để thắng hung tàn\nLấy chí nhân để thay cường bạo.\nTrận Bồ Đằng sấm vang chớp giật\nMiền Trà Lâm trúc chẻ tro bay.\nSĩ khí đã hăng,\nQuân thanh càng mạnh.\nTrần Trí, Sơn Thọ nghe hơi mà mất vía,\nLý An, Phương Chính nín thở cầu thoát thân.\nThừa thắng ruổi dài, Tây Kinh quân ta chiếm lại\nTuyển binh tiến đánh, Đông Đô đất cũ thu về.\nNinh Kiều máu chảy thành sông, tanh trôi vạn dặm\nTuyên Độ thây chất đầy nội, nhơ để ngàn năm.\nPhúc tâm quân giặc, Trần Hiệp đã phải bêu đầu\nMọt gian kẻ thù, Lý Lượng cũng đành bỏ mạng.\nVương Thông gỡ thế nguy, mà đám lửa cháy lại càng cháy\nMã Anh cứu trận đánh, mà quân ta hăng lại càng hăng.\nBó tay để đại bại vong, giặc đã trí cùng lực kiệt\nChẳng đánh mà người chịu khuất, ta đây mưu phạt tâm công.\nTưởng chúng biết lẽ ăn năn, nên đã thay lòng đổi dạ\nNgờ đâu vẫn đường mưu tính, lại còn chuốc tội gây oan.\nGiữ ý kiến một người, gieo vạ cho bao nhiêu kẻ khác\nTham công danh một lúc, để cười cho tất cả thế gian.\n(Nguyễn Trãi, Bình Ngô đại cáo, Bản dịch của Bùi Kỷ)",
