      "sectionName": "Sử dụng Tiếng Việt (300đ)",
      "passage": "Dựa vào thông tin dưới đây để trả lời các câu từ 26 đến 30:\nNếu đã lâu rồi bạn không nghe thấy tin tức gì về tầng ozone, đó là vì tình hình đang khá sáng sủa. Câu\nchuyện phục hồi và bảo vệ tầng ozone đã chứng tỏ rằng khi khoa học và quyết tâm chính trị hợp lực,\nthế giới có thể thay đổi vận mệnh của mình.Năm 1985, các nhà khoa học khí quyển ở Nam Cực phát\nhiện một điều đáng lo ngại: tầng ozone đang trên đà biến mất trong vòng mấy mươi năm tới. Từ đây,\ncộng đồng quốc tế bắt đầu thảo luận và hành động – với một tốc độ chưa từng có. Chỉ 2 năm sau đó,\nvào ngày 16-9-1987, Nghị định thư Montreal về các chất làm suy giảm tầng ozone được thông qua.\nTua nhanh đến ngày hôm nay: tầng ozone đang trên đà hồi phục, trở thành phông nền sáng lạn cho\nmột câu chuyện đầy cảm hứng và nhiều bài học về nhân loại, gợi mở cho chúng ta những con đường\nđể giải quyết các khủng hoảng môi trường khác.\nKhoa học vào vai thám tử\nTầng ozone nằm ở độ cao khoảng 15–40 km so với bề mặt Trái Đất, thuộc tầng bình lưu và có vai trò\nnhư một lớp \"kem chống nắng\" che chắn cho hành tinh khỏi tia cực tím (UV). Nếu không có lá chắn\nnày, ánh nắng Mặt Trời sẽ trở nên cực kỳ nguy hiểm với con người và hầu hết các loài động – thực\nvật. Đặc biệt, tia UV-B (thứ làm cho da bị cháy nắng) ở cường độ cao có thể dẫn đến nhiều loại ung thư.\nĐồng lòng\nNăm 1986, Liên Hiệp Quốc bắt đầu đàm phán về một hiệp ước xóa sổ các hóa chất có hại cho tầng\nozone – chủ yếu là CFC. Một trong những tiếng nói chính trong các cuộc đàm phán là Stephen An-\ndersen, khi đó là chuyên gia của Cơ quan Bảo vệ Môi trường Mỹ (EPA). Nhóm của ông đã vạch ra\nhàng trăm giải pháp – một cách có hệ thống – để loại bỏ dần CFC từ hàng trăm lĩnh vực công nghiệp,\ngiúp việc chuyển đổi trở nên dễ dàng và khả thi trên toàn thế giới.Nghị định thư Montreal có hiệu lực\ntừ năm 1989, và đến tận năm 2008 là hiệp định môi trường đầu tiên và duy nhất của Liên Hiệp Quốc\nđược mọi quốc gia trên thế giới phê chuẩn.\n(Theo Báo Tuổi Trẻ Cuối Tuần, ngày 30-10-2021)",
      "clusterId": "kscl_vietnamese_c26",
      "question": "Câu nào sau đây không thể hiện thái độ của người viết đối với việc bảo vệ tầng ozone?",
