      "question": "CA-PIU-LÉT PHU NHÂN – Con nghĩ sao? Con liệu có ưng chàng quý tộc này không? Tối nay, con sẽ thấy chàng ở buổi dạ yến nhà ta. Con hãy ngắm nhìn dung mạo của chàng Pa-rit trẻ tuổi như nhìn vào trang sách quý, con sẽ thấy vẻ thanh tao hiện ra dưới nét bút tuyệt trần. Con hãy nhìn kỹ từng nét cân đối của chàng, nét nọ như làm tăng vẻ đẹp của nét kia. Và nếu trên trang sách đó còn nét nào chưa rõ, thì như lời chú ghi bên lề sách, đôi mắt chàng sẽ làm sáng tỏ. Chàng chưa từng gắn bó với một ai, chẳng như một tập tình ca quý giá chỉ cần một tấm bìa bọc lại là nên thiên tuyệt tác! Chàng như cá kia cần vẫy vùng nơi biển cả, và nếu vẻ đẹp bên trong lại được thêm vẻ đẹp bên ngoài ấp ủ thì thật là cảnh tuyệt vời. Quyển sách cũng được dự phần vinh hạnh dưới mắt bao người, khi cái móc gài bằng vàng của nó được ôm ấp những uẩn văn chương cũng quý giá như vàng. Kết duyên cùng chàng, con được chung hưởng mọi kho tàng quý báu của chúng, mà riêng phần con chẳng thiệt thòi sút kém gì. (Uy-li-am Sếch-xpia, Rô-mê-ô và Giu-li-ét, theo Văn bản đọc hiểu Ngữ văn 11, NXB Đại học Huế, 2023) Cách khắc họa nhân vật chàng Pa-rit trong đoạn trích trên được thể hiện chủ yếu qua:",
