      "sectionName": "Sử dụng Tiếng Việt (300đ)",
      "passage": "Dựa vào thông tin dưới đây để trả lời các câu từ 56 đến 60:\n“Tác phẩm văn học và đọc văn học thật là một hiện tượng diệu kì. Theo các nhà khoa học quan sát,\nkhi chưa đọc, văn bản in chỉ là một vật, một khách thể, nhưng khi đã đọc thì dần dần khách thể đó biến\nmất, sách vẫn còn đó nhưng đồng thời lại “biến mất” để nhường chỗ cho thế giới hình tượng, sách từ\nbên ngoài chuyển vào trong nội tâm người đọc, người đọc hóa thân vào nhân vật trong sách.\nTại sao khi đọc sách ta bỗng toàn tâm toàn ý suy nghĩ vào những điều chưa bao giờ nghĩ tới? Hóa ra\nta suy nghĩ bằng những ngôn từ, hình tượng của nhà văn, còn nhà văn thì phát biểu bằng tâm hồn, trí\ntuệ của ta! Cho nên tuy biết rõ tác phẩm là của nhà văn mà ta vẫn thấy có toàn quyền giải thích, hứng\nthú giải thích và khi nói là ta giải thích, ta ấy đâu phải là chính ta! Nhà văn chiếm chỗ trong tâm trí ta,\ncòn ta thì chiếm tác phẩm của họ! Cho nên tác phẩm văn học là một sản phẩm lạ lùng, nó gần như xóa\nbỏ ranh giới giữa ta và tác giả. Người đọc không phải “đệm”, mà đã “chơi” tác phẩm trên bản nhạc\ncủa nhà văn, do vậy tùy theo người “chơi” mà tác phẩm có sự khác nhau.”\n(Trần Đình Sử, Đọc văn học văn, NXB Giáo dục, 2001, tr. 6–7)",
