      "clusterId": null,
      "question": "Ngày xưa có một người tên là Yết Kiêu ở làng Hạ-bi làm nghề đánh cá. Một hôm, ông ta đi dọc theo bờ biển về làng, bỗng thấy trên bãi có hai con trâu đang ghì sừng húc nhau dưới bóng trăng khuya. Sẵn đòn gánh, ông cầm xông lại phang mạnh mấy cái vào mình chúng nó. Tự dưng hai con trâu chạy xuống biển rồi biến mất. Ông rất kinh ngạc, đoán biết là trâu thần. Khi nhìn lại đòn gánh thì thấy có mấy cái lông trâu dính vào đấy. Ông mừng quá bỏ vào miệng nuốt đi. Từ đó sức khỏe của Yết Kiêu vượt hẳn mọi người, không một ai dám đương địch. Đặc biệt là có tài lội nước. Mỗi lần ông lặn xuống biển bắt cá, người ta cứ tưởng như ông đi trên đất liền. Nhiều khi ông sống ở dưới nước luôn sáu bảy ngày mới lên. (Nguyễn Đông Chi, Yết Kiêu, theo Kho tàng truyện cổ tích Việt Nam, tập 1, NXB Giáo dục, 2000) Dựa theo nội dung truyện, đặc điểm nổi bật nhất của nhân vật Yết Kiêu là gì?",
