      "question": "Huống gì thành Đại La, kinh đô cũ của Cao Vương: Ở vào nơi trung tâm trời đất, được cái thế rồng cuộn hổ ngồi. Đã đúng ngôi nam bắc đông tây, lại tiện hướng nhìn sông dựa núi. Địa thế rộng mà bằng, đất đai cao mà thoáng. Dân cư khỏi chịu cảnh khốn khổ ngập lụt, muôn vật cũng rất mực phong phú tươi tốt. Xem khắp đất Việt ta, chỉ nơi này là thắng địa. Thật là chốn tụ hội trọng yếu của bốn phương đất nước; cũng là nơi kinh đô bậc nhất của đế vương muôn đời. Trẫm muốn dựa vào sự thuận lợi của đất ấy để định chỗ ở. Các khanh nghĩ thế nào? (Nguyễn Đức Vân dịch, in trong Thơ văn Lý – Trần, tập I, NXB Khoa học Xã hội, Hà Nội, 1977, tr. 229 – 230) Lý do chính khiến Lý Công Uẩn lựa chọn thành Đại La làm kinh đô mới được thể hiện trong đoạn văn trên là gì?",
