      "passage": null,
      "clusterId": null,
      "question": "Cho đoạn thơ sau: “Lao xao chợ cá làng ngư phủ; Dắng dỏi cầm ve lầu tịch dương. Lẽ có Ngu cầm đàn một tiếng, Dân giàu đủ khắp đòi phương.” ( Cảnh ngày hè, Nguyễn Trãi) Từ “tịch dương” trong câu thơ có nghĩa là gì?",
