      "sectionName": "Sử dụng Tiếng Việt (300đ)",
      "passage": "Dựa vào thông tin dưới đây để trả lời các câu từ 81 đến 85:\nVai hề đóng vai trò quan trọng trong các vở chèo vì trào lộng là một đặc trưng của loại hình nghệ\nthuật này, tương tự như sân khấu cổ truyền các nước Đông Nam Á khác. Hề cốt mua vui cho khán giả,\nnhất là trong các vở có cảnh buồn. Theo quan niệm sân khấu của Sếch-xpia (Shakespeare), đời là sự\npha trộn của hạnh phúc và khổ đau. Trong chèo, vai hề và các cảnh vui cười là dịp để cho người dân\nđả kích những thói hư, tật xấu của xã hội phong kiến, kể cả vua quan, những người có quyền, có của\ntrong xóm làng. Hề chèo được phép chế nhạo thoải mái cũng như những anh hề trong cung điện của\nvua chúa châu Âu. Có hai loại nhân vật trào phúng trong chèo: loại chính là hề, bao gồm hề mồi (hề\nnhảy múa không dùng gậy) và hề gậy (hề nhảy múa với gậy), thường là người hầu. Loại thứ hai có\nthể xuất hiện trong nhiều vai khác nhau, chẳng hạn như thầy bói, cô đồng, lão say, xã trưởng. Đôi khi\nnhững nhân vật này gây ra tiếng cười không liên quan trực tiếp đến vở diễn, vì hề (hay thầy bói, lão\nsay,.) có thể bình luận về các nhân vật, về xã hội nói chung.\n(Hữu Ngọc, Lady Borton (Chủ biên), Chèo (Popular theatre), NXB Thế giới, Hà Nội, 2008, tr. 21-22)",
      "clusterId": "kscl_vietnamese_c81",
      "question": "Đặc điểm, ý nghĩa nổi bật nhất của vai hề trong nghệ thuật chèo là gì?",
      "options": [
        "A. Hề chèo là nhân vật phụ thường xuất hiện ngẫu nhiên nhằm tạo không khí vui vẻ, giúp khán giả thư giãn trong các phân đoạn trữ tình hoặc kịch tính căng thẳng.",
        "B. Hề chèo xuất hiện chủ yếu trong các vở diễn hài kịch, không đóng vai trò then chốt trong việc truyền tải nội dung hay định hướng tư tưởng cho tác phẩm.",
        "C. Hề chèo mang lại tiếng cười trào phúng sâu sắc, giúp giải trí nhưng cũng nhằm phê phán hiện thực và bộc lộ quan điểm xã hội của người dân một cách sinh động.",
        "D. Nhân vật hề trong chèo chủ yếu thực hiện các động tác vũ đạo hoặc hoạt cảnh sân khấu, thể hiện tính truyền thống trong hình thức biểu diễn cổ điển của nghệ thuật dân gian."
      ],
      "correctAnswer": 2,
      "explanation": "Đáp án đúng là C."
