      "passage": null,
      "clusterId": null,
      "question": "Ngày xưa, ở một làng kia, có một nông dân rất nghèo, cha già đau yếu lâu ngày không tiền thuốc men phải chết. Gặp hôm trời mưa gió lớn nước ngập lụt, anh không mượn ai khiêng giúp đi chôn được, lại không tiền mua áo quan, đành lấy chiếc chiếu độc nhất trong nhà bó thây cha lại rồi một mình vác ra nghĩa địa. Đến một chỗ nước xoáy mạnh, anh ta trượt chân ngã, nước lũ cuốn trôi xác cha đi mất. Anh lần mò tìm kiếm mãi không thấy, đành phải bỏ về nhà, trong lòng hết sức áy náy. Đến khuya, anh nằm mơ thấy một con rồng hiện đến van xin anh hãy đưa thây cha đi chôn nơi khác chứ để vào hàm rồng vướng đau nó tội nghiệp. Anh hỏi xác cha ở đâu thì rồng bảo là hiện đang kẹt ở khe đá ngoài cửa sông, và nơi đó chính là hàm rồng. Hôm sau, anh y theo lời rồng dặn, đến tìm xác cha thì thấy bị mắc ở khe đá thật, bèn đưa đi ra gò cao chôn cất. [. . . ] (Trích Lọ thuốc trường sanh) Văn bản trên thuộc thể loại nào sau đây?",
