      "question": "Đọc đoạn trích và trả lời câu hỏi dưới đây. Cậu lấy làm sung sướng vì có người lắng nghe chuyện mình. “Anh học đọc sách như thế nào?” cô muốn biết. “Trong trường học, như mọi người khác, cậu đáp. “Nhưng nếu anh đọc sách được thì sao anh chỉ thành một người chăn cừu bình thường thôi?” Cậu bối rối vì tin chắc rằng cô sẽ không hiểu nổi cậu. Để tránh né trả lời, cậu tiếp tục kể về hành trình của mình và đôi mắt nhỏ phảng phất mắt người Mauren của cô gái khi tròn xoe, lúc nheo lại vì kinh ngạc. Thời gian trôi qua, còn cậu thầm ước ngày hôm ấy đừng bao giờ chấm dứt, hoặc là bố cô cứ tiếp tục để cậu chờ thêm ba ngày nữa. Cậu thấy một cảm giác khác lạ chưa từng biết đến: đó là mơ ước được sống ổn định một nơi. Có cô gái này bên cạnh thì sẽ chẳng còn ngày nào là nhàm chán nữa. (Paulo Coelho, Nhà giả kim, NXB Hội Nhà văn, Hà Nội, 2020) Mơ ước của nhân vật chính thể hiện khát vọng gì?",
