      "sectionName": "Sử dụng Tiếng Việt (300đ)",
      "passage": "Dựa vào thông tin dưới đây để trả lời các câu từ 111 đến 115:\nChắc các bạn đã nghe câu chuyện về người mẹ yếu ớt đã nhấc cả chiếc ô tô đế cứu con bị đè ở dưới.\nĐó là điển hình sống của sức mạnh tiềm tàng phi thường trong chúng ta. Con người có những khả\nnăng kì diệu, có điều vì những khả năng này thường không được phát huy nếu như ta không thường\nxuyên đánh thức chúng dậy. Những ai khơi dậy được cái sức mạnh tiềm ẩn đó sẽ thành đạt, còn ai cứ\nđể mặc nó thì hãy chờ đợi một cuộc đời tầm thường. Có một báo cáo nói rằng con người chúng ta chỉ\nmới sử dụng có 15% tiềm năng thực sự của mình. Nếu ta sử dụng được 20% thì sẽ là thiên tài, còn\nnếu dùng đến 30% thì sẽ là vĩ nhân.\nDo đó có thể nói bất kì thiên tài hay vĩ nhân nào cũng đều có sự đánh thức tài năng lên mức cao hơn\nso với nguời thường. Edison thường lặp đi lặp lại một thí nghiệm đến 20 lần hoặc hơn mới có được\nmột phát minh và ông đã trở thành một thiên tài nhờ không ngừng phát huy khả năng còn ẩn giấu của\nmình, đánh thức cái thiên năng đang thiêm thiếp ngủ trong mình.\nSự tự tin là điều hết súc quan trọng. Ai đó có thể làm được rất nhiều tiền và có một quyền lực lớn,\nsong tiền bạc và quyền lực chỉ là những thứ thuộc về con người, được sử dụng cho con ngưởi. Người\nta không thể thoả mãn chỉ vì họ có những thứ ấy rồi, họ phải luôn giữ được phong độ, nếu không chỉ\ncòn là cái bóng của dĩ vãng mà thôi. Nếu họ không có được những nỗ lực để vươn lên, để thường\n\n\nxuyên trau dồi bản thân, thì họ sẽ phải tụt hậu vì rất khó giữ nguyên được vị trí của mình - không có\ncon đường nào khác ngoài sự tiến lên hay lùi xuống. Tại vì nếu bạn đứng nguyên một chỗ, trong khi\nnhững người khác tiến lên thì chính là bạn đang tụt xuống vậy.\nBạn phải không ngừng phát triển bản thân. Triết gia người Pháp Henri Bergson nói rằng tiến bộ chính\nlà bản chất của cuộc sống. Mọi vật sống đều phải phát triển một cách tích cục và điều đó thường được\ncoi là nguyên tắc của sự sống.\nDo vậy ta phải thường xuyên để ý đến bước tiến của mình và cần thông minh hơn, sáng suốt hơn và\ntốt hơn. Ta phải độ lượng với người khác song phải nghiêm khắc với bản thân, phải cẩn thận để khỏi\nsa vào vũng dễ dãi và duy lí. Ta không thể chinh phục được người khác nếu không chinh phục chính\nbản thân mình trước. Nếu bạn tự coi mình chẳng ra gì thì chớ nên trách người khác cũng nghĩ về bạn\nnhư vậy. [...] Hãy nhớ rằng nếu mụốn bạn có thể đánh thức được tài năng đang ngủ của mình đấy, cứ\nmạnh dạn thử xem.\n(Trích Thế giới quả là rộng lớn và có rất nhiều việc phải làm, Kim Woo Choong, dịch từ bản tiếng Anh, NXB Văn hoá\nThông tin, 2003, tr. 195 - 199)",
      "clusterId": "kscl_vietnamese_c111",
      "question": "Trong cụm “sa vào vũng dễ dãi và duy lí”, từ duy lí gần nghĩa nhất với:",
      "options": [
        "A. Thực dụng, luôn đặt lợi ích vật chất lên trên hết.",
        "B. Biện minh, hợp lí hoá cho sai lầm của bản thân.",
        "C. Lối suy nghĩ đề cao lí trí một cách cứng nhắc, máy móc, thiếu linh hoạt và tình cảm.",
        "D. Dựa dẫm, ỷ lại vào người khác, thiếu tự lực."
      ],
      "correctAnswer": 2,
      "explanation": "Đáp án đúng là C."
