      "clusterId": null,
      "question": "Đá vẫn trơ gan cùng tuế nguyệt, Nước còn chau mặt với tang thương. Nghìn năm gương cũ soi kim cổ, Cảnh đấy, người đây luống đoạn trường. (Bà Huyện Thanh Quan – Thăng Long thành hoài cổ, Hợp tuyển thơ văn Việt Nam, tập III, NXB Văn hoá, 1962) Nghệ thuật nổi bật trong đoạn thơ sau thể hiện đặc trưng của thể loại nào trong thơ trung đại?",
