      "passage": null,
      "clusterId": null,
      "question": "Đọc đoạn văn sau và xác định luận đề chính của văn bản: Con người từ khi ra đời đã tồn tại cái tôi. Cái tôi còn được gọi bằng nhiều tên khác: cái ta, ngã, tự ngã. Cái tôi được hình thành ngay từ khi con người sinh ra và qua tiếp xúc với thế giới bên ngoài, cái tôi dần học cách cư xử sao cho kiểm soát được những ham muốn vô thức không được xã hội chấp nhận. Cái tôi là sự tin tưởng mạnh mẽ rằng bạn là một cá nhân riêng lẻ. Nếu không có cái tôi, không những bạn mà tất cả chúng ta sẽ rơi vào sự hoang mang suốt cuộc hành trình đi tìm bản thân mình. Mỗi người đều có cái tôi riêng, không ai giống ai, từ đó hình thành nên tính cách của mỗi người rất khác nhau, dù chúng ta cùng sống trong một xã hội. Và con người luôn cần khác biệt. Cái tôi có vai trò trung gian hòa giải giữa những ham muốn vô thức và những tiêu chuẩn nhân cách và xã hội. Nhưng cái tôi dễ theo khuynh hướng tự do của bản năng, thích nổi loạn, bất tuân quy luật trật tự, vì vậy con người luôn phải canh chừng cái tôi để uốn nắn, điều chỉnh, hướng dẫn nó khỏi đi chệch đường, xây dựng và phát triển một nhân cách trưởng thành. (Từ Happy New Year, cần hiểu rõ cái tôi là gì, dẫn theo tuoitre.vn)",
