      "clusterId": "kscl_vietnamese_c146",
      "question": "Trong truyện ngắn Bức tranh (Nguyễn Minh Châu), chi tiết “cái ghế cắt tóc” được xây dựng với ý nghĩa nghệ thuật gì nổi bật?",
      "options": [
        "A. Là hình ảnh tượng trưng cho khoảng cách xã hội giữa người lính cũ và nghệ sĩ nay thành đạt.",
        "B. Là chi tiết gợi tả không gian đời thường, giúp khắc họa rõ hơn bối cảnh thành phố hiện tại.",
        "C. Là điểm nút thắt của cốt truyện, nơi quá khứ và hiện tại giao nhau, thúc đẩy sự thức tỉnh lương tri.",
        "D. Là biểu tượng cho sự trở lại của chiến tranh, gợi cảm giác bất an khi người kể chuyện đối diện quá khứ."
      ],
      "correctAnswer": 2,
      "explanation": "Đáp án đúng là C."
