      "question": "Câu chuyện bắt vợ số 3: Khoảng năm 1947, có bốn người lạ đến bắt một người đàn bà góa rất đẹp gái tên là Hầu Thị Dua ở Thái An về Lũng Hồ làm vợ. Cô về làm vợ người ta được hai năm. Sau, thấy sống ở nhà chồng có nhiều chuyện không như ý, cô sầu não mà tự vẫn. Năm cô mất, mới chỉ 25 tuổi đời. Bình luận: Câu chuyện về Hầu Thị Dua là một bi kịch của tục bắt vợ. Đồng thời, ta gặp lại ở đây một hành động mang căn cước tộc người, một lối nổi loạn chống lại số phận khác kiểu H’Mông: bế tắc thì tự vẫn. (Trích Những đỉnh núi du ca – một lối tìm về cá tính H’Mông, Nguyễn Mạnh Tiến, NXB Thế Giới, Hà Nội, 2014, tr. 187 – 189) Vấn đề chính được đề cập trong đoạn trích là gì?",
