      "section": "vietnamese",
      "sectionName": "Sử dụng Tiếng Việt (300đ)",
      "passage": null,
      "clusterId": null,
      "question": "Cuộc thi gồm ba kỳ, mỗi kỳ phải vượt qua một đợt sóng. Con vật nào đủ sức, đủ tài vượt qua cả ba kỳ mới đậu để được hóa Rồng. Trong một tháng trời, bao nhiêu loài thủy tộc đến thi đều bị loại, vì không con nào vượt được cả ba đợt sóng. Có con cá rô nhảy qua được một đợt, nhưng đợt sau thì rớt. Có con tôm nhảy qua được hai đợt, ruột gan vẫy vẫy, râu đuôi đã gần hóa rồng, nhưng đến đợt ba thì đuối sức bị té nên lưng cong lại. Đến lượt một con cá chép vào cuộc thi. Con cá này vốn đã là loài quý hiếm đặc biệt, trong miệng lại ngậm một viên ngọc trai. Thần Gió thấy lạ bay đến xem, gió mây ào ạt kéo đến, sấm sét ầm trời, những đợt sóng cao trỗi dậy, đưa cá chép ào ào vượt qua cả ba đợt sóng, tới Vũ Môn, nhả ngọc và hóa Rồng. Do đó mà trong dân gian có câu ca dao về việc cá chép hóa Rồng: Mồng ba cá đi ăn thề,/ Mồng bốn cá về cá vượt Vũ Môn. (Theo: http://truyenxuatichcu.com/than-thoai-viet-nam) Dòng nào sau đây thể hiện đặc trưng hình thức nghệ thuật của văn bản trên?",
