      "clusterId": null,
      "question": "Mặc dù Quang rất chăm viết thư nhưng cũng giống như tôi, đến mãi bấy giờ anh mới được hồi âm. Song lá thư cho anh hay một cái tin rất tệ. Vợ anh đã bỏ nhà theo trai. Cô ta tằng tịu với một gã thủy thủ đường sông, đến nỗi mang bầu nên phải bỏ làng, bán xới theo gã vào Nam ngay sau ngày hòa bình. Bị phải cái tin điếng người ấy, Quang tỏ ra bình tĩnh. Anh thông cảm với vợ. “Lấy nhau mới được có bảy ngày là tớ lên đường đi Bê. Như vậy là cô ấy đã phải vò võ chịu đựng những mười năm trời có lẻ chứ nào ít ỏi gì đâu, thế mà sức người thì có hạn\" - Quang điềm đạm lý giải một cách phân minh - \"Thêm nữa, nhà tớ lại kề ngay một bến sông nhộn nhịp, tứ xứ thuyền bè qua lại, sự thể như thế tất phải xảy ra. Trách ai được bây giờ. Thôi thì sự đã vậy thì đành vậy, tớ chẳng thiết!”. Miệng anh nói vậy nhưng bụng anh nói khác. Đêm đêm, giữa canh khuya, Quang chỉ toàn nằm mộng thấy kẻ bội bạc, anh nấc lên tên cô ta và vừa rên ư ử vừa nói lảm nhảm. Có đêm tôi nghe thấy trong màn anh vẳng ra tiếng khóc thút thít, sụt sịt. (Trích Rửa tay gác kiếm - Bảo Ninh, NXB Trẻ, 2021.) Đặc điểm nhân vật Quang trong đoạn trích được thể hiện rõ nhất qua chi tiết nào?",
