      "passage": null,
      "clusterId": null,
      "question": "Hê-ra-clét tới xứ sở của chị em E-xpê-rít. Chàng gặp thần Át-lát đang khom lưng, giơ vai chống đội bầu trời, đầu cúi gục, nhọc nhằn, mệt mỏi. Đó là hình phạt của Dớt đối với Át-lát vì vị thần này xưa kia đã đứng về phía những Ti-tăng, những vị thần già, chống lại thần Dớt. Hê-ra-clét cất tiếng nói: Hỡi thần Át-lát, một Ti-tăng con của U-ra-nốt bao la và của Gai-a vĩ đại, đang phải chịu khổ hình! Ta là Hê-ra-clét, con của đấng phụ vương Dớt, đến đây để làm một việc không phải do trái tim ta muốn. Nhà vua Ơ-ri-xtê sai ta đi lấy những quả táo vàng ở khu vườn cấm do ba tiên nữ E-xpê-rít trông coi. Xin Ti-tăng Át-lát hãy giúp ta trong việc này. Thần Át-lát đáp lại: Hỡi Hê-ra-clét, ta sẵn sàng giúp đỡ. Nhưng ai sẽ thay ta chống đỡ bầu trời? Nhà ngươi liệu có thể thay ta làm việc đó trong chốc lát? Hê-ra-clét nhận lời, ghé vai vào chống đỡ bầu trời. Một sức nặng ghê gớm chưa từng thấy đè lên vai và lưng chàng. Gân cốt trong người chàng căng ra, mồ hôi đổ như tắm. Nhưng nhờ nữ thần A-tê-na luôn bên chàng truyền sức lực, Hê-ra-clét vẫn đứng vững cho đến khi Át-lát trở về với ba quả táo vàng. (Theo Thần thoại Hy Lạp, tập II, Nguyễn Văn Khỏa biên soạn, NXB Đại học và Trung học chuyên nghiệp, Hà Nội, 1986.) Chi tiết “Hê-ra-clét ghé vai chống đỡ bầu trời” trong đoạn trích có ý nghĩa gì?",
