      "sectionName": "Sử dụng Tiếng Việt (300đ)",
      "passage": null,
      "clusterId": null,
      "question": "Tôi sẽ viết về những cảnh đói khổ, về những sự áp bức, về những nỗi trái ngược bất công. Tôi sẽ đứng về những con người lầm than bị đày đọa, bị lăng nhục. Tôi sẽ vạch trần ra những vết thương xã hội, những việc làm bạo ngược lộng hành của xã hội thời bấy giờ. Tôi sẽ gánh nhận lấy mọi trách nhiệm, chống đối cũng như bào chữa bảo vệ. Tôi sẽ chỉ có tiến bước, chỉ có đi thẳng. Tôi sẽ chỉ biết có ánh sáng. Và chính tôi là ánh sáng.Chao ôi, có thế thì còn gì làm tôi đáng sống hơn nữa? Thế thì có sự hạnh phúc và sự giàu có nào đánh đổi và so sánh được? Thế là không những tôi chỉ đọc sách khuya mà còn đi ăn lang thang suốt canh khuya. Tôi vừa đi vừa thì thầm tự nhủ, nhiều lúc vung hẳn tay lên như một nhà hùng biện trước một diễn đàn có tranh luận với hàng nghìn người nghe đứng về phía mình và cũng hàng nghìn người đứng về phía đối lập. Và tôi dang rộng không những chỉ có đôi cánh tay mà còn căng hết ngực lên như để đón, để che lấy lẽ phải và sự thật của mình. (Trích Nhà thơ ở ngõ Nghè, Nguyên Hồng, in trong Bước đường viết văn, NXB Văn nghệ TP. Hồ Chí Minh, 2000, tr. 30–32) Tác dụng của câu hỏi tu từ “Chao ôi, có thế thì còn gì làm tôi đáng sống hơn nữa?” là gì?",
