      "passage": null,
      "clusterId": null,
      "question": "Lom khom trong ngôi nhà ngói mũi phố Hàng Nâu Tôi nhẩm đọc những bài thơ xưa của cụ Không ớt mà cay – một đời ăn lương vợ Đem bút nghiên giờ bàn chuyện trăm năm. Đánh đùa vui con làm lính, bố làm quan Thơ phú Tú Xương khóc cười cùng phố chợ Câu thơ hay thường nói lời thương vợ Dẫu là bậc Thi nhân cũng cần yên ấm một mái nhà. (Hoài Khánh, in trong Đi cùng thương nhớ, NXB Văn học, Hà Nội, 2020, tr. 33) Nhân vật trữ tình trong đoạn thơ có tâm trạng như thế nào khi nhớ về nhà thơ Tú Xương?",
