      "question": "Kể từ khi thành lập vào năm 2015, MYCL đã không ngừng cải thiện công nghệ sợi nấm, tạo ra vô số sản phẩm dựa trên vải da được “nuôi trồng”. MYCL phát triển sợi nấm trong các phòng thí nghiệm nhỏ, gần các nguồn chất thải nông nghiệp. Họ tận dụng bã thừa từ các đồ n dùng dầu cọ làm giá thể, nhằm tăng thêm lợi ích là ngăn các chất thải này bị đốt cháy và gây ô nhiễm. Các giá thể này cung cấp chất dinh dưỡng cho sợi nấm mà MYCL đưa vào đó. Sợi nấm sẽ phát triển và xâm chiếm hoàn toàn giá thể trong khoảng hai tuần. Để tạo ra vật liệu Mylea, họ để nấm phát triển trong khoảng năm đến sáu tuần. Quá trình tạo Mylea không quá phức tạp, tuy nhiên việc tinh chỉnh thành phần giá thể và điều kiện phát triển như vệ sinh, nhiệt độ, độ ẩm và ánh sáng là điều cần thiết. Nghĩa là đối với mỗi quy trình sản xuất, cần có một công thức cụ thể để đảm bảo chất lượng của Mylea được nhất quán. (Ngô Thành, “Giải pháp phát triển vật liệu da làm từ sợi nấm trồng trên chất thải nông nghiệp”, theo tiasang.com.vn.) Mục đích chính của đoạn trích là gì?",
