      "sectionName": "Sử dụng Tiếng Việt (300đ)",
      "passage": "Dựa vào thông tin dưới đây để trả lời các câu từ 236 đến 240:\nTHẦY LANG DỐT\nCó thầy lang nọ, cứ động ai hỏi bệnh gì là y như giở sách tra. Đã thế lại dốt.\nMột lần, có người nhà nửa đêm chạy đến tìm thầy, nhờ thầy cứu người bệnh đau bụng nặng. Thầy thắp\nđèn, lấy sách ra tra, rồi bảo:\n– Đi mua mấy lạng nhân sâm về sắc lấy nước mà uống.\nNgười bệnh uống nhân sâm vào, càng đau, đến sáng thì chết.\nNgười nhà đâm đơn kiện. Thầy bị đưa lên cửa công.\nQuan hỏi:\n– Thầy bốc thuốc thế nào lại để người ta chết như thế?\nThầy trả lời, vẻ chắc chắn:\n\n\n– Bẩm, tôi bốc thuốc có sách, chứ đâu phải bốc bậy đâu ạ! Sách dạy thế nào, tôi cứ làm thế ấy.\nQuan hỏi đến sách, thầy đưa sách ra. Giở đến trang có bài thuốc nhân sâm, cuối trang có ghi:\n\"Phúc thống phục nhân sâm\"\n(Nghĩa là: đau bụng uống nhân sâm)\nNhưng chưa chấm câu. Giở sang trang bên kia thì thấy thêm hai chữ:\n\"Tắc tử\"\n(Nghĩa là: thì chết).\n(Trương Chính, Truyện cười dân gian chọn lọc, NXB Giáo dục, 1985)",
