      "passage": null,
      "clusterId": null,
      "question": "Bờ sông hoang dại như một bờ tiền sử. Bờ sông hồn nhiên như một nỗi niềm cổ tích tuổi xưa. Chao ôi, thấy thèm được giật mình vì một tiếng còi xúp-lê của một chuyến xe lửa đầu tiên đường sắt Phú Thọ – Yên Bái – Lai Châu. Con hươu thơ ngộ ngẩng đầu nhung khỏi áng cỏ sương, chăm chăm nhìn tôi lừ lừ trôi trên một mũi đò. Hươu vểnh tai, nhìn tôi không chớp mắt mà như hỏi tôi bằng cái tiếng nói riêng của con vật lành: \"Hỡi ông khách sông Đà, có phải ông cũng vừa nghe thấy một tiếng còi sương?\". Đàn cá dầm xanh quẫy vọt lên mặt sông bụng trắng như bạc rơi thoi. Tiếng cá đập nước sông đuổi mất đàn hươu vụt biến. Thuyền tôi trôi trên \"Dải sông Đà bọt nước lênh bênh – Bao nhiêu cảnh bấy nhiêu tình\" của \"một người tình nhân chưa quen biết\" (Tản Đà). Dòng sông quãng này lững lờ như nhớ thương những hòn đá thác xa xôi để lại trên thượng nguồn Tây Bắc. Và con sông như đang lắng nghe những giọng nói êm êm của người xuôi, và con sông đang trôi những con đò mình nở chạy buồm vải – nó khác hẳn những con đò đuôi én thắt mình dây cổ điển trên dòng trên. (Nguyễn Tuân toàn tập, tập IV, NXB Văn học, Hà Nội, 2000.) Đoạn trích trên thể hiện đặc trưng nổi bật nào của thể loại tuỳ bút?",
