      "passage": null,
      "clusterId": null,
      "question": "Kẻ kỵ sĩ ở hạt Quốc Oai, họ Văn tên là Dĩ Thành, tính tình hào hiệp, không chịu để ma quỷ mê hoặc. Phàm những hoa yêu nguyệt quái và dâm thần lệ quỷ không được liệt vào tự điển, chàng đều coi thường, không sợ hãi gì. Cuối đời Trùng Quang nhà Trần, người chết chóc nhiều, những oan hồn không chỗ tựa nương, thường họp thành từng đàn từng lũ, hoặc gõ cửa hàng cơm để kiếm miếng ăn, hoặc đón cô gái chơi để kết duyên tạm. Ai va chạm thì bệnh nguy khốn, ai cầu cúng thì thấy hết phép hay, hoành hành ở đồng nội không biết kiêng sợ gì cả. Dĩ Thành nhân lúc say rượu, cưỡi ngựa đi ra, bọn ma quỷ sợ hãi, đều tan chạy cả. Chàng kịp gọi bảo rằng: - Các người đều là những kẻ tráng sĩ, không may mắc nạn. Ta nay đến thăm, muốn đem điều lợi hại nói chuyện, xin đừng lảng tránh như vậy. Ma quỷ lại dần dần họp lại, mời chàng lên ngồi phía trên. Dĩ Thành hiểu bảo rằng: - Lũ ngươi cứ thích làm cho người ta phải tai nạn, làm cho người ta phải chết chóc, chẳng hay cốt để làm gì? Chúng nói: - Chúng tôi muốn để thêm quân. - Các ngươi muốn cho thêm quân nhưng tổn hại người sống thì sao! Quân thêm thì ăn uống phải thiếu, người bớt thì cung cấp phải thưa, lợi gì cho các ngươi mà cứ thích làm như vậy? (Trích Chuyện tướng Dạ Xoa - Nguyễn Dữ, theo Việt điện u linh tập - Nam Ông mộng lục - Truyền kỳ mạn lục, NXB Văn học, 2008.) Hành động và lời nói của nhân vật Dĩ Thành trong đoạn trích cho thấy điều gì về con người ông?",
