      "question": "Người con trai không mảnh vải che thân Như củ khoai trui trần vùi trong cát Người con gái vô tình bắt gặp Tình yêu ra đời trước cả mọi lễ nghi. Đứng cao hơn mọi thành kiến giàu nghèo Không tính toán sang hèn, không đẳng cấp Đôi trai gái khỏa thân đầu tiên trong văn học Mượn chính mình để thổ lộ tình yêu. (Trích Sông Hương Thơ (1983 - 2003) tuyển chọn, NXB Văn hóa Thông tin, 2003.) Phong cách ngôn ngữ chính được sử dụng trong đoạn thơ trên là gì?",
