      "sectionName": "Sử dụng Tiếng Việt (300đ)",
      "passage": null,
      "clusterId": null,
      "question": "Bu em đong cho tôi cả bốn hào gạo đỏ, đừng đong gạo trắng ăn nhạt lắm. Vợ gật đầu: - Cũng được, nhưng đã thật khỏi chưa? Tôi trông thầy em còn mệt lắm. - Ốm luôn sáu tháng trời làm mà không mệt sao được? Đi đi. - Đi ngay giờ à? - Ừ, đi xuống nhà bà phó Cửu ấy, xa một tí nhưng được rẻ. Vợ gật đầu bảo thằng cu: - Con ngồi đây với thầy cho bu đi đong gạo nhé? Nó không chịu, sợ sệt nhìn cha. Chị mắng: - Con nhà vô phúc, lại sợ bố!. Khốn nạn, tại đi về không có tiền mua bánh cho nó nên nó giận đấy mà, phải tội chết, con ạ. Nhưng anh đĩ Chuột bảo: - Cho cả nó đi, kẻo nó khóc. Bảo cái Gái về tôi bảo. Người cha khốn nạn nhìn đứa con chòng chọc, thở dài. Một giọt lệ từ từ lăn xuống chiếu. - Thầy bảo gì con ạ? - Lúc nãy mẹ con mày ăn cám phải không? Gái gượng cười cãi: - Ăn chè đấy chứ! (Trích Nghèo - Nam Cao, theo Nam Cao - Truyện ngắn chọn lọc, NXB Văn học, Hà Nội, 2000.) : Bu em đong cho tôi cả bốn hào gạo đỏ, đừng đong gạo trắng ăn nhạt lắm. Vợ gật đầu: - Cũng được, nhưng đã thật khỏi chưa? Tôi trông thầy em còn mệt lắm. - Ốm luôn sáu tháng trời làm mà không mệt sao được? Đi đi. - Đi ngay giờ à? - Ừ, đi xuống nhà bà phó Cửu ấy, xa một tí nhưng được rẻ. Vợ gật đầu bảo thằng cu: - Con ngồi đây với thầy cho bu đi đong gạo nhé? Nó không chịu, sợ sệt nhìn cha. Chị mắng: - Con nhà vô phúc, lại sợ bố!. Khốn nạn, tại đi về không có tiền mua bánh cho nó nên nó giận đấy mà, phải tội chết, con ạ. Nhưng anh đĩ Chuột bảo: - Cho cả nó đi, kẻo nó khóc. Bảo cái Gái về tôi bảo. Người cha khốn nạn nhìn đứa con chòng chọc, thở dài. Một giọt lệ từ từ lăn xuống chiếu. - Thầy bảo gì con ạ? - Lúc nãy mẹ con mày ăn cám phải không? Gái gượng cười cãi: - Ăn chè đấy chứ! (Trích Nghèo - Nam Cao, theo Nam Cao - Truyện ngắn chọn lọc, NXB Văn học, Hà Nội, 2000.) Đoạn hội thoại trong trích đoạn \"Nghèo\" (Nam Cao) phản ánh sâu sắc nhất điều gì về người cha?",
