      "passage": null,
      "clusterId": null,
      "question": "Con người lúc đó sống đến 900 tuổi, đến hạn cũng chết, nhưng được vào vườn Din-giang-ca(4) của Chử Lầu. Ở đó trong mười hai ngày tự nhiên lột da, sống và trẻ lại rồi trở về nhà cũ. Nhưng có một nhà nọ, nàng dâu xích mích với mẹ chồng, thường hát húi xỉa và nén mẹ chồng giận, quyết ở luôn tại vườn Din-giang-ca không về. Ở đây bà ta ăn quả đào trắng, uống nước suối, phạm vào lệnh cấm của Chử Lầu, làm cho Chử Lầu giận, bèn cấm loài người không được đến vườn của mình nữa. Từ đó, loài người hễ chết là chết luôn. Lúc đó công việc làm đồng rất nhẹ nhàng. Cỏ không có, cây cối tự nhiên mọc và có quả. Ngô ăn được cả lá. Người ta chỉ mất công gieo ngô và lúa là có ăn. Mỗi lần lúa chín tự nhiên nó bay về, không phải gặt. Nhưng một người kia có phần việc là mang cơm ra đồng cho mọi người ăn, thấy nhóm mình làm việc quá nhanh chóng; vừa đặt cơm ở chỗ này thì họ đã tiến cách đó rất xa. Người ấy bèn xin Chử Lầu hiện cỏ ra mặt đất để cho công việc chậm lại. Chử Lầu nghe lời. Vì thế mà từ đó công việc đồng áng rất chật vật. Lại có một nhà khác có người đàn bà nhác không chịu quét dọn nhà cửa để đón lúa nên lúc lúa bay về thấy bẩn thỉu bèn rủ nhau từ đấy quyết không tụ về nữa [.]. (Tư liệu tham khảo văn học Việt Nam, tập I; Văn học dân gian, phần III, NXB Giáo dục, 1976) Nội dung chính của đoạn trích trên phản ánh điều gì về thế giới và con người thời kỳ nguyên sơ?",
