      "sectionName": "Sử dụng Tiếng Việt (300đ)",
      "passage": null,
      "clusterId": null,
      "question": "Rất nhiều người khác ở tuổi tôi đã chứng minh bản thân bằng sự liều lĩnh và chiêu trò bứt phá giới hạn. Chinh phục một cung đường đầy nguy hiểm trong những đêm dài mỏi mệt, mù quáng lao ra đường đi đến một nơi bất định và trở về an toàn. Liều lĩnh dẹp bỏ những luật chơi, bẻ gãy các cam kết, lao ra đường như những con ngựa bất kham và làm những điều không ai ngờ đến. Anh hùng trở thành mệnh lệnh. Khao khát khẳng định mình trở thành cơn đói chẳng bao giờ dứt. Tôi đói khát ánh mắt thán phục của bạn bè xung quanh. Anh đói khát những tiếng trầm trồ đắm đuối của các cô gái trẻ. Cô đói khát lời khen ngợi lấp lánh nơi những người xung quanh. Tuổi trẻ quay cuồng quanh quỹ đạo của sự hào hoa, yêng hùng và bứt phá giới hạn. Và rồi, chớp mắt giữa cuộc chinh phạt của những chiến binh điên rồ đó, tôi chùn giáo gươm và hành trình ngông cuồng, khi thoáng tự hỏi mình đang làm như vậy vì điều gì? Vì sao phải thể hiện? Vì sao phải gồng lưng chứng tỏ? Vì sao phải khoác chiếc áo quá nặng lên một thân thể yếu ớt và dễ tổn thương? [.] Tôi là ai giữa một ngàn người đứng trên sân trường ấy? Tôi là ai giữa hàng chục ngàn bàn chân bước qua cuộc đời vô danh ấy? Câu hỏi đau đáu thôi thúc những hành động cầu kỳ và tàn bạo - bất chấp cả sự sống để được biết đến. Nhưng hóa ra “làm chính mình” lại chỉ là một ngọn đèn trang trí nhấp nháy. Sau tất cả, kẻ cuối cùng nhìn tôi trong gương là chính tôi. Tại sao tôi phải đập nát chiếc gương đó để làm chính mình – như hào quang người khác muốn? (Ta có bi quan không?, Khải Đơn) Dòng nào sau đây thể hiện vấn đề tư tưởng trung tâm của đoạn trích?",
