      "id": "vact-kscl-vietnamese-q261",
      "section": "vietnamese",
      "sectionName": "Sử dụng Tiếng Việt (300đ)",
      "passage": "Dựa vào thông tin dưới đây để trả lời các câu từ 261 đến 265:\nTứ thơ chính là hạt nhân kết cấu hình tượng thơ trữ tình. Nó đứng ở vị trí trung tâm của quá trình sáng\n\n\ntạo thơ ca, chi phối sự liên kết tất cả các yếu tố của bài thơ lại thành một chỉnh thể thống nhất. Nó cấp\ncho cái \"hỗn mang\" của những rung động hay những \"nỗi niềm tinh vân\" (chữ dùng của Huy Cận)\nmột trật tự, khiến chúng hoàn toàn có thể được phô bày bằng các phương tiện ngôn từ diễn ra trong\nthời gian, để thực sự trở thành những rung động thơ, nỗi niềm thơ. Tứ thơ quy định tính sáng tạo của\nhình tượng thơ, phân biệt hình tượng thơ mang tính cô đọng, khái quát, thấm đẫm cảm xúc và dồn\nnén suy nghĩ với những hình ảnh rời rạc, cá biệt của hiện thực khách quan. Trong sáng tác, người ta\nthường nói đến sự \"lóe sáng\" của tứ thơ. Đúng hơn phải nói là sự \"lóe sáng\" của tư duy nghệ thuật khi\ntứ thơ vụt đến. Quả là, xét trên tổng thể, tứ thơ mang tính chất \"khải thị\", giúp cho nhà thơ ngay lập\ntức trong một giây lát ngắn ngủi nào đó nhận ra tính chất toàn vẹn của vấn đề, của sự vật, hiện tượng\nđang đối diện với mình và thách thức cảm xúc, suy nghĩ của mình. Sự \"lóe sáng\" của tứ cũng đồng\nnghĩa với việc nhà thơ trong phút chốc tìm được con đường giải phóng những ý niệm của mình thoát\nkhỏi tính trừu tượng, để nó được hóa thân vào những hình ảnh tươi mới của hiện thực. Và chính sự\ngiải phóng này cũng tạo ra tiền đề quan trọng cho phép nhà thơ thực sự khám phá được mình – một\nsự khám phá được đặt ở trung tâm của mối liên hệ, tương tác giữa chủ quan và khách quan. Nói khái\nquát lại, tứ thơ chính là một sự phát hiện – phát hiện của nhà thơ về bản thân và về thế giới.\n(Phan Huy Dũng, Tứ thơ như là hạt nhân kết cấu của hình tượng thơ trữ tình, Tạp chí Diễn đàn Văn nghệ Việt Nam, số\n10/1999, tr. 21–22)",
      "clusterId": "kscl_vietnamese_c261",
