      "question": "“Ào một cái, từ trong rừng dâu da bỗng như có tiếng quẫy động của một con vật khổng lồ. Ông Diễu biết là con đầu đàn đã đến. Con khỉ này cũng gớm lắm đây. Nó xuất hiện với một nghi lễ vương chủ. Tự tin đến thô bạo. Ông Diễu mỉm cười và chăm chú nhìn.” (Nguyễn Huy Thiệp – Muối của rừng) Hiện tượng tách biệt trong cách diễn đạt “Tự tin đến thô bạo” có tác dụng biểu đạt gì?",
