      "passage": null,
      "clusterId": null,
      "question": "VŨ NHƯ TÔ – Xây Cửu Trùng Đài? ĐAN THIÊM – Phải. VŨ NHƯ TÔ – Xây Cửu Trùng Đài cho một tên bạo chúa, một tên thoán nghịch, cho một lũ gái dâm ô? Tôi không thể đem tài ra làm một việc ô uế, muôn năm làm bia miệng cho người đời được. ĐAN THIÊM – Ông biết một mà không biết hai. Ông có tài, tài ấy phải đem cống hiến cho non sông, không nên để mục nát với cỏ cây. Ông không có tiền, ông không có thể dựng lấy một toà đài như ý nguyện. Chấp kinh, phải tòng quyền. Đây là lúc ông nên mượn tay vua Hồng Thuận mà thực hành cái mộng lớn của ông. Ông kể tiếng, đó là tiểu tiết. Ông cứ xây lấy một toà đài cao cả. Vua Hồng Thuận và lũ cung nữ kia rồi mất đi, nhưng sự nghiệp của ông còn lại về muôn đời. Dân ta nghìn thu được hãnh diện, không phải thẹn với những cung điện đẹp của nước ngoài, thế là đủ. Hậu thế sẽ xét công cho ông, và nhớ ơn ông mãi mãi. Ông hãy nghe tôi làm cho đất Thăng Long này thành nơi kinh kỳ lộng lẫy nhất trần gian. VŨ NHƯ TÔ – Đa tạ. Bà đã khai cho cái óc u mê này. Thiếu chút nữa, tôi nhỡ cả. Những lời vàng ngọc tôi xin lĩnh giáo. Trời quá yêu nên tôi mới được gặp bà. ĐAN THIÊM – Tôi cũng may được gặp ông. Xin ông cố đi. Đức vua ngự tới. ( Nguyễn Huy Tưởng, Vũ Như Tô, trong Kiệt tác sân khấu thế giới – Vũ Như Tô, NXB Sân khấu, Hà Nội, 2006, trang 35–39) Đặc điểm ngôn ngữ kịch trong đoạn trích thể hiện rõ nhất ở phương diện nào sau đây?",
