      "question": "Sơn Tinh không hề nao núng. Thần dùng phép lạ bốc từng quả đồi, dời từng dãy núi, dựng thành lũy đất, ngăn chặn dòng nước lũ. Nước sông dâng lên bao nhiêu, đồi núi cao lên bấy nhiêu. Hai bên đánh nhau ròng rã mấy tháng trời, cuối cùng, Sơn Tinh vẫn vững vàng mà sức Thủy Tinh đã kiệt. Thần Nước đành rút quân. Từ đó, oán nặng, thù sâu, hằng năm, Thủy Tinh làm mưa gió, bão lụt dâng nước đánh Sơn Tinh. Nhưng năm nào cũng vậy, Thần Nước đánh mỏi mệt, chán chê vẫn không thắng nổi Thần Núi để cướp Mị Nương, đành rút quân về. ( Ngữ văn 6, tập một, NXB Giáo dục Việt Nam, 2018 ) Chi tiết cuộc chiến giữa Sơn Tinh và Thủy Tinh trong đoạn trích chủ yếu mang ý nghĩa gì?",
