      "question": "Tính thần Sét rất nóng nảy: hễ Ngọc Hoàng sai là đi ngay, hễ thấy là đánh liền, cho nên cũng có lúc làm cho người, vật chết oan. Vì thế mà thần Sét đã có lần bị Ngọc Hoàng phạt vì đánh lầm, giết hại kẻ vô tội. Người ta kể chuyện: có lần thần bị bắt nằm im một nơi, không cựa quậy, trong một đám rừng ở thiên đình. Con gà thần của Ngọc Hoàng được lệnh thỉnh thoảng lại mổ một cái, làm cho thần đau nhói cả người nhưng không biết làm thế nào được. Khi được Ngọc Hoàng tha, thần có thói quen là hễ thấy hoặc nghe tiếng gà là giật mình. Mỗi lần có chớp rạch, biết thần Sét sắp xuống, người hạ giới thường bắt chước tiếng gà để dọa thần, có lẽ cũng vì thế. Thần Sét kể ra thì cực oai, cực dữ, nhưng không ai có thể tưởng tượng được rằng thần bị thua Cường Bạo Đại Vương. Mặc dầu ông Cường Bạo sau rồi cũng bị thần Sét đánh chết, nhưng câu chuyện này đã một dạo làm cho cả thiên đình xấu hổ. (Theo Nguyễn Đổng Chi – Tác phẩm được tặng Giải thưởng Hồ Chí Minh, Sđd, tr. 87 – 88) Đặc điểm nào sau đây thể hiện rõ đặc trưng thể loại văn học dân gian trong đoạn trích về Thần Sét?",
