      "question": "Do triết lí quân bình âm dương, ngay cả hộ pháp ở chùa cũng có ông Thiện, ông Ác (Thiện trước, Ác sau). Chính triết lí quân bình âm dương này tạo ra ở người Việt một khả năng thích nghi cao với mọi hoàn cảnh (lối sống linh hoạt), dù khó khăn đến đâu vẫn không chán nản. Người Việt Nam là dân tộc sống bằng tương lai (tinh thần lạc quan): thời trẻ khổ thì tin rằng về già sẽ sướng, suốt đời khổ thì tin rằng đời con mình sẽ sướng (“Không ai giàu ba họ, không ai khó ba đời”.). Một ví dụ điển hình cho tinh thần lạc quan lạ kì đó là bài ca dao miền Trung về “Mười quả trứng”. (Trần Ngọc Thêm, Cơ sở văn hóa Việt Nam, NXB Giáo dục, TP. Hồ Chí Minh, 2011) Theo đoạn trích, đặc điểm nổi bật trong tư duy văn hoá của người Việt là gì?",
