      "passage": "Dựa vào thông tin dưới đây để trả lời các câu từ 143 đến 150:\nMore than 30,000 feet below the surface of the Pacific Ocean, scientists have uncovered an extraordi-\nnary new ecosystem that challenges what we know about life on Earth. In one of the planet’s deepest\nocean trenches, researchers encountered dense colonies of red-tipped tubeworms rising like under-\nwater skyscrapers, iridescent snails crawling along their surfaces, and bristly white creatures weav-\ning between them. The discovery, described in the journal Nature, marks the world’s deepest known\necosystem sustained by chemical reactions rather than sunlight, revealing that life can flourish in\nplaces once thought utterly inhospitable.\nLed by Mengran Du of China’s Institute of Deep-sea Science and Engineering, the team used the\nsubmersible Fendouzhe to explore the Kuril-Kamchatka and Aleutian trenches, stretching between\nRussia and Alaska. These regions lie within the hadal zone–an environment named after Hades, the\nGreek god of the underworld–where immense pressure, frigid temperatures, and total darkness pre-\nvail. The expedition’s success signals major technological advances in deep-sea exploration, allowing\nscientists to observe a biological world that had remained hidden for millennia. “People know very\nlittle about the bottom of the trench,” Du said. “For decades, we simply lacked the technology to go\nthere.”\nUnlike most ecosystems on Earth that rely on sunlight and photosynthesis, this newly discovered\ncommunity survives through chemosynthesis–a process in which bacteria convert chemicals such as\nmethane and hydrogen sulfide into energy. These gases seep from the ocean floor, fueling microbes\nthat live symbiotically inside tubeworms and mollusks. The microbes transform toxic compounds into\norganic matter, nourishing their hosts and creating the foundation of the food web. Analysis suggests\nthat the methane originates not from geological activity deep within the Earth, but from microorgan-\nisms in the sediment itself–a discovery that rewrites scientists’ understanding of deep-ocean chem-\nistry.\nThe researchers found life on 19 of 23 dives, suggesting that such hadal ecosystems might be far more\ncommon than previously believed. Each specimen collected could represent a species new to science,\nthough further study is needed to confirm this. Scientists are also eager to understand how these an-\nimals withstand crushing pressure at such depths–possibly through unique biochemical adaptations.\nBeyond its ecological importance, the finding carries cosmic implications: if life can thrive in the\nsunless trenches of Earth, similar chemosynthetic ecosystems could exist in the subsurface oceans of\ndistant worlds, such as Jupiter’s icy moon Europa. “This discovery expands the boundaries of where\nlife can exist,” said Dominic Papineau, an exobiologist who co-authored the study. “If it can survive\nhere, it could survive elsewhere in the universe.”\n(Adapted from: https://www.washingtonpost.com/climate-environment/2025/07/30/deep-sea-discovery-pacific-ocean/)\nChoose an option (A, B, C, or D) that best answers each question.",
