      "sectionName": "Sử dụng Tiếng Anh (300đ)",
      "passage": "Dựa vào thông tin dưới đây để trả lời các câu từ 293 đến 300:\n1. Tigers in India likely encounter humans every day, yet attacks on humans remain surprisingly rare.\nGiven that tigers can and do kill almost any animal they encounter, including elephants and rhinos,\nit seems unusual that they do not frequently attack humans. Historically, British writers such as Jim\nCorbett depicted a period when villages in India were under constant threat from man-eating tigers.\nHowever, these accounts may have overstated the frequency of attacks. There were far more tigers\nduring Corbett’s time (around 60,000 in the subcontinent compared to only about 3,000 today), so\nattacks on humans were likely as rare then as they are now, in proportion to the tiger population.\n2. The common assumption is that tigers are afraid of humans, but the reasons behind this fear are not\nentirely clear. Can tigers truly recognize that humans may be better armed than they are? It’s unlikely.\nIt’s more plausible that the reason tigers don’t attack humans lies not in pre-programmed ancestral\nlogic, but in how tigers perceive us visually. Since the 1950s, ethology–the study of animal behavior\nfrom the animal’s perspective–has shed light on animal behavior in a more accurate way. This ap-\nproach suggests that rather than attributing human-like motives to animals, we should consider how\nanimals themselves view and interact with their environment.\n3. Tigers’ visual perception of humans may explain their lack of aggression. A tiger sees a standing\nhuman, who may be about 1.8 meters tall, as a large entity. In the tiger’s eyes, the human might appear\nup to 6 meters long because of their upright posture. This is very different from how the tiger would\nperceive a prey animal. When a tiger looks at the human from the front, the human seems huge, but\nfrom the side, the human virtually disappears. This could be very disorienting for the tiger, and a\npredator must feel confident to tackle its prey. This confusion may explain why tigers, unlike lions,\nwhich often hunt in groups and take risks, are more cautious and reluctant to engage in conflict with\nhumans.\n4. Interestingly, if the theory about the visual confusion caused by standing humans is true, the op-\nposite should be the case for squatting humans. A squatting person is much smaller and has a wider\nprofile, resembling a medium-sized deer, a more typical target for a tiger. Despite this, tigers tend to\nattack humans who are squatting or bending over, such as villagers gathering grass for fodder. This\nsuggests that tigers are more likely to view squatting humans as prey, which is less confusing for them\nvisually.\n5. Thus, the human tendency to stand upright may not only distinguish humans from nearly all other\nspecies but also play a role in protecting humans from becoming prey. Standing humans are perceived\nas more intimidating and harder for a tiger to gauge properly, leading to fewer attacks compared to\nother species or even other predators like lions.\n(Adapted from: IELTS PLUS Volume 2 Reading Test 1 + Adjusted by Hoài Sơn)\nChoose an option (A, B, C, or D) that best answers each question.",
