      "explanation": "Chọn A\nSau Chiến thắng 30/4/1975, đất nước Việt Nam hoàn toàn thống nhất, Nhà nước Việt\nNam thực hiện quyền quản lý trên toàn bộ lãnh thổ, bao gồm đất liền, vùng biển, vùng\ntrời, quần đảo Hoàng Sa và Trường Sa.\nViệc quản lý này có ý nghĩa chính trị – pháp lý đặc biệt quan trọng:\n- Hai quần đảo này là bộ phận không thể tách rời của lãnh thổ Việt Nam. Việc quản lý\ntoàn diện sau chiến tranh là hành động khẳng định rõ ràng rằng Việt Nam đã thu hồi và\nquản lý đầy đủ tính toàn vẹn của đất nước, từ đất liền đến hải đảo.\n- Đây là sự thể hiện cao nhất của chủ quyền quốc gia đối với vùng biển và hải đảo. Việc\nthực thi quản lý hành chính, quốc phòng và dân sự tại hai quần đảo là bằng chứng hùng\nhồn nhất về quyền lực tối cao và độc lập của Nhà nước Việt Nam trên phạm vi lãnh thổ\ncủa mình.\n+ B đây là hệ quả kinh tế – đối ngoại, không phải ý nghĩa chủ yếu về chính trị – lãnh thổ\nsau năm 1975.\n+ C đây là ý nghĩa kinh tế, nhưng không phải mục tiêu trọng tâm của việc quản lý toàn\nbộ lãnh thổ sau thống nhất.\n+ D sau 1975, Việt Nam chưa phải là thành viên tích cực trong các tổ chức quốc tế về\nbiển (như UNCLOS 1982 sau này mới tham gia). Vì vậy, ý nghĩa này không phù hợp với\nbối cảnh lịch sử ngay sau khi thống nhất đất nước."
