      "correctAnswer": 2,
      "explanation": "Chọn C\nSách trắng là một loại tài liệu chính thức được Chính phủ công bố. Việc này nhằm mục\nđích minh bạch hóa lập trường, cung cấp các chứng cứ pháp lý và lịch sử (như bản đồ\ncổ, tài liệu triều Nguyễn,.) ra trước cộng đồng quốc tế. Hành động này khẳng định rằng\nViệt Nam không chỉ bảo vệ chủ quyền bằng sức mạnh (quản lý thực tế) mà còn bằng luật\npháp quốc tế, kêu gọi sự ủng hộ và công nhận từ các nước khác. Đây là hình thức đấu\ntranh văn minh, hiệu quả và phù hợp với xu thế chung của thế giới.\n- A. Đây là hoạt động quản lý thực tế (thực thi chủ quyền trên thực địa), không phải là ý\nnghĩa trực tiếp của việc công bố Sách trắng.\n- B. Sau 1975, lãnh thổ Việt Nam đã thống nhất, không có sự thay đổi biên giới lãnh thổ\nnào đáng kể. Việc công bố Sách trắng về chủ quyền Hoàng Sa, Trường Sa (1979, 1981,\n1988) nhằm bảo vệ chủ quyền trước các hành động xâm phạm từ bên ngoài, không phải\nlà chuyển đổi lãnh thổ.\n- D. Việc công bố Sách trắng có tác dụng tuyên truyền trong nước, góp phần nâng cao\nnhận thức và sự đồng thuận nhưng mục tiêu chủ yếu vẫn là đấu tranh pháp lý và ngoại\ngiao trên trường quốc tế. Do đó, đây chỉ là ý nghĩa phụ, không phải ý nghĩa quan trọng\nnhất."
