      "passage": "Dựa vào thông tin dưới đây để trả lời các câu từ 52 đến 54:\nSau Đại thắng Xuân 1975, Nhà nước Cộng hòa xã hội chủ nghĩa Việt Nam quản lý toàn bộ lãnh thổ\nđất nước, trong đó có quần đảo Hoàng Sa và quần đảo Trường Sa. Trong các năm 1979, 1981, 1988,\nViệt Nam liên tục công bố Sách trắng khẳng định chủ quyền lãnh thổ, lãnh hải của Việt Nam.\nĐể bảo vệ chủ quyền biển đảo quốc gia, Việt Nam triển khai nhiều hoạt động thực thi chủ quyền ở\nhuyện đảo Hoàng Sa và huyện đảo Trường Sa: triển lãm các hiện vật, xây dựng bia chủ quyền, thiết\nlập ngọn hải đăng, xây chùa, trường học, bưu điện, hỗ trợ cuộc sống người dân,.”.\n(Sách giáo khoa Lịch sử 12, bộ Chân trời sáng tạo, trang 59)",
