      "passage": "Dựa vào thông tin dưới đây để trả lời các câu từ 73 đến 75:\nPhản ứng giữa $\\text{CaCO}_3(s)$ và $\\text{HCl}(aq)$ được biểu diễn bằng phương trình cân bằng:\n$$\\text{CaCO}_3(s) + 2\\text{HCl}(aq) \\to \\text{CaCl}_2(aq) + \\text{CO}_2(g) + \\text{H}_2\\text{O}(l)$$\nHọc sinh T thực hiện một loạt các phản ứng để nghiên cứu các yếu tố ảnh hưởng đến tốc độ của phản ứng. Trong mỗi thử nghiệm, học sinh cho $50{,}0\\text{ mL}$ $\\text{HCl}(aq)$ phản ứng với $1{,}00\\text{ g}$ $\\text{CaCO}_3(s)$ ở $21{,}2^\\circ\\text{C}$ và đo thời gian cần thiết để phản ứng kết thúc. Các dữ liệu được đưa ra trong bảng sau:\n| Thử nghiệm | Nồng độ $\\text{HCl}(aq)$ (M) | Kích thước hạt $\\text{CaCO}_3(s)$ | Thời gian phản ứng kết thúc (giây) |\n| :---: | :---: | :---: | :---: |\n| 1 | 1,00 | Bột mịn | 67 |\n| 2 | 1,00 | Các viên nhỏ | 112 |\n| 3 | 1,00 | Các viên lớn | 342 |\n| 4 | 3,00 | Bột mịn | 22 |\n| 5 | 3,00 | Các viên nhỏ | 227 |\n| 6 | 3,00 | Các viên lớn | 114 |\nCho biết: Tăng nồng độ, nhiệt độ, áp suất và diện tích bề mặt sẽ làm tăng tốc độ phản ứng, trong khi chất xúc tác làm tăng tốc độ phản ứng mà không bị tiêu hao trong phản ứng.",
