      "passage": "Dựa vào thông tin dưới đây để trả lời các câu từ 76 đến 78:\nCảm biến áp suất (Pressure sensor) là thiết bị dùng để đo áp suất của chất khí hoặc chất lỏng, sau đó\nchuyển đổi đại lượng áp suất thành tín hiệu điện để xử lý, hiển thị hoặc điều khiển.\nTrong thực tế, cảm biến áp suất được sử dụng rất rộng rãi trong ô tô, hệ thống thủy lực, khí nén, máy\nbơm, trạm khí, và y sinh học (máy đo huyết áp điện tử).\nNguyên lý hoạt động cơ bản: khi áp suất tác dụng lên màng cảm biến, màng bị biến dạng một lượng\nrất nhỏ. Sự biến dạng này làm thay đổi một đại lượng vật lý có thể đo được, ví dụ:\nThay đổi điện trở (cảm biến kiểu điện trở ứng suất – strain gauge sensor).\nThay đổi điện dung (cảm biến tụ điện).\nThay đổi điện áp do hiệu ứng áp điện (cảm biến piezoelectric).\nMột dạng phổ biến là cảm biến áp suất điện trở ứng suất, hoạt động dựa trên hiệu ứng:\nR = ρ l\nS\nKhi màng cảm biến bị nén hay kéo giãn, chiều dài l và tiết diện S thay đổi → điện trở R thay đổi theo\n→ mạch điện chuyển thành tín hiệu điện tỉ lệ với áp suất.\nÁp suất thường được đo bằng: p = F\nS trong đó F là lực tác dụng (N), S là diện tích chịu lực (m2).",
