      "question": "Xét các phát biểu sau về cảm biến áp suất: (1) Cảm biến áp suất chỉ dùng để đo chất khí, không đo được chất lỏng. (2) Áp suất càng lớn thì biến dạng màng cảm biến càng nhiều. (3) Trong cảm biến piezoelectric, áp suất tạo ra điện áp do hiệu ứng áp điện. (4) Cảm biến áp suất có thể dùng để đo cả áp suất tuyệt đối và áp suất chênh lệch. Có bao nhiêu phát biểu đúng?",
