      "explanation": "Chính sách thực hiện trong 3 năm, tính từ 2012\nSố người nghiên cứu trong nước năm 2012 là: 150\nSố người nghiên cứu quốc tế năm 2012 là: 64\nTrong 1 năm:\nSố người nghiên cứu trong nước: 30% chuyển sang Quốc tế, số lượng gốc còn 70%\nSố người nghiên cứu quốc tế: 15% chuyển sang Trong nước, số lượng gốc còn 85%\nChu kì 1: 2013\nSố người nghiên cứu trong nước là: 70%.150 + 15%.64 = 114,6\nSố người nghiên cứu quốc tế là: 85%.64 + 30%.150 = 99,4\nChu kì 2: 2014\nSố người nghiên cứu trong nước là: 70%.114,6 + 15%.99,4 = 95,13\nSố người nghiên cứu quốc tế là: 85%.99,4 + 30%.114,6 = 118,87\nChu kì 3: 2015\nSố người nghiên cứu trong nước là: 70%.95,13 + 15%.118,87 = 84,4215\nSố người nghiên cứu quốc tế là: 85%.118,87 + 30%.95,13 = 129,5785\nXét các phương án:\nNhiều hơn 130 − 95\n95 = 36,84 % so số người nghiên cứu trong nước trong năm 2014\nNhiều hơn 130 − 84\n84 = 54,76 % so số người nghiên cứu trong nước trong năm 2015\nCó 1 phát biểu đúng là (I)\nVậy chọn B\n\n\n3.2. SUY LUẬN KHOA HỌC"
