      "correctAnswer": 0,
      "explanation": "Đáp án A\na) sai, vì trong thực tế người ta thực hiện ở nhiệt độ khoảng 450 – 500◦C.\n⇒ Phản ứng tổng hợp NH 3 xảy ra ở nhiệt độ khá cao và phải duy trì nhiệt độ đó trong\ntháp suốt quá trình phản ứng. Từ hình 3.7, ta thấy trong cấu tạo tháp phản ứng có cuộn\nđốt nóng → chứng tỏ phải luôn cung cấp nhiệt cho tháp phản ứng → nhiệt tỏa ra do\nphản ứng không đủ để đốt nóng hỗn hợp N 2 và H 2 mới cho vào và duy trì nhiệt độ\ntrong tháp ở 450 – 500 ◦C.\nb) sai, vì theo ngữ liệu “Ammonia được tổng hợp từ khí nitrogen và khí hydrogen.\nĐây là phản ứng thuận nghịch và tỏa nhiệt. Theo nguyên lý chuyển dịch cân bằng Le\nChaterlie, muốn cân bằng chuyển dịch về phía tạo thành ammonia thì cần phải hạ nhiệt\nđộ và tăng áp suất. . . ” Khi cân bằng chuyển dịch về phía ammonia thì hiệu suất phản\nứng tạo thành NH 3 sẽ tăng.\nc) sai, vì theo ngữ liệu “. . . dùng chất xúc tác là sắt kim loại được hoạt hóa bằng hỗn\nhợp Al 2 O 3 và K 2 O để làm cho cân bằng nhanh chóng được thiết lập”.\nNhư vậy, chất xúc tác chỉ làm cho cân bằng nhanh được thiết lập mà không làm chuyển\ndịch cân bằng ⇒ Hiệu suất không thay đổi.\nd) đúng, vì theo đoạn ngữ liệu ”Hỗn hợp khí đi ra từ tháp tổng hợp (gồm có N 2, H 2 và\nNH 3) được dẫn đến tháp làm lạnh. Ở đây, khí amoniac hóa lỏng và được tách riêng ra,\ncòn hỗn hợp khí N 2 và H 2 chưa phản ứng được đưa trở lại tháp tổng hợp”\n⇒ Khi làm lạnh thì chỉ có NH 3 bị hoá lỏng còn N 2 và H 2 vẫn đang ở thể khí, chứng\ntỏ NH 3 có nhiệt độ hoá lỏng cao hơn N 2."
