      "passage": "Dựa vào thông tin dưới đây để trả lời các câu từ 106 đến 108:\nAn lo lắng khi sử dụng điện thoại di động thì năng lượng của các xung sóng điện từ có thể làm tăng nhiệt độ của não giống như hiệu ứng lò vi sóng. Vì vậy, An thực hiện thí nghiệm: Để điện thoại hoạt động $360\\text{ s}$ trong $50\\text{ g}$ nước. Các thông tin cần thiết được An ghi lại trong bảng sau:\n| Đại lượng | Giá trị |\n| :--- | :--- |\n| Số xung sóng điện từ phát ra trong $1\\text{ s}$ | $216$ |\n| Năng lượng của mỗi xung sóng điện từ (J) | $12 \\cdot 10^{-5}$ |\n| Công suất tiêu thụ của điện thoại (W) | $0{,}2$ |\n| Nhiệt dung riêng của nước ($\\text{J}/(\\text{g}\\cdot\\text{K})$) | $4{,}2$ |",
