      "passage": "Dựa vào thông tin dưới đây để trả lời các câu từ 112 đến 114:\nTại Đại hội đại biểu toàn quốc lần thứ VI của Đảng (năm 1986), khi đề ra đường lối đổi mới, Đảng bắt\nđầu từ việc đổi mới tư duy, mà trước hết là tư duy kinh tế. Kinh tế được điều tiết theo chuyển động thị\ntrường - vấn đề tưởng như là nguyên lý nhưng đặt vào bối cảnh khởi động Đổi mới năm 1986 khi đất\nnước đang lâm vào khủng hoảng kinh tế - xã hội, mới thấy hết giá trị mang tính mở đường của công\ncuộc đổi mới.\nChứng kiến những bước đi đầu tiên của công cuộc đổi mới, chuyên gia kinh tế Võ Đại Lược cho rằng:\n“Kết luận quan trọng nhất của Đại hội Đảng toàn quốc lần thứ VI là xóa bỏ cơ chế kế hoạch hóa quan\nliêu, bao cấp nhưng phải đến năm 1989, công cuộc đổi mới mới bắt đầu có kết quả thật sự bằng việc\nchống lạm phát, được dư luận đánh giá rất cao”.\nĐiều quan trọng là chúng ta thực hiện quá trình tự do hóa kinh tế, tức là xóa mệnh lệnh, bao cấp và\nthực hiện quan hệ thị trường, không thu mua lúa gạo của nông dân như trước đây, không bao cấp lương\nthực cho thành phố nữa mà để hoàn toàn cho thị trường quyết định quan hệ lưu thông hàng hóa, lưu\nthông giữa nông thôn và thành thị.\n(Báo VOV, https://vov.vn/chinh-tri)",
