      "passage": "Dựa vào thông tin dưới đây để trả lời các câu từ 130 đến 132:\nKhoán đảm bảo là một thuật ngữ chỉ mức cam kết của nhà nước/doanh nghiệp đối với một lĩnh vực\nnào đó về tài chính/sản xuất/kinh doanh. Trong bài này, được hiểu là mức tiền nhà nước đứng ra chi\ntrả (đảm bảo) khi một khu vực làm ăn thua lỗ\nNếu xem doanh thu là 100%, thì mức độ lỗ được tính bằng chênh lệch phần trăm giữa doanh thu và\nphần trăm của số tiền lỗ trong tổng doanh thu của loại nông sản đang xét. Riêng nếu phần tiền lỗ\nmà lớn hơn doanh thu, thì mức độ lỗ bằng phần trăm số tiền lỗ trong doanh thu đó. Dưới đây là mức\nkhoán nhà nước đảm bảo cho nền nông nghiệp nước ta.\nĐể hiểu rõ hơn về khoán đảm bảo, ta hãy phân tích thực trạng sản xuất một số nông sản của vùng\nĐồng Bằng sông Cửu Long, từ việc tính toán lợi nhuận (lời/lỗ), ta biết được nhà nước đảm bảo khoán\nnhư thế nào và kết luận được lợi nhuận cuối cùng.",
