      "passage": "Dựa vào thông tin dưới đây để trả lời các câu từ 136 đến 138:\nTua-bin gió là thiết bị chuyển hóa năng lượng của gió thành điện năng, hoạt động dựa trên nguyên lý\ncảm ứng điện từ và định luật bảo toàn năng lượng.\nKhi gió thổi, các cánh quạt của tua-bin nhận động năng của không khí, làm quay trục rôto. Trục này\nđược nối với máy phát điện xoay chiều, nơi cơ năng quay được chuyển hóa thành điện năng. Chuỗi\nchuyển hóa năng lượng trong tua-bin gió:\nĐộng năng của gió Cơ năng quay Điện năng\nCông suất của dòng gió có thể tính theo biểu thức: P = 1\n2ρAv3\ntrong đó:\nρ: khối lượng riêng của không khí (≈ 1,2 kg/m3),\nA: diện tích quét của cánh quạt (A = πr2),\nv: vận tốc gió (m/s).\nTrong thực tế, chỉ một phần năng lượng gió được chuyển thành điện do tổn hao và giới hạn Betz\n(≈ 59% là hiệu suất lý thuyết tối đa).",
