      "explanation": "Đáp án: C\nGiải thích:\nCác thuốc kháng virus thường ức chế hoạt động của các enzyme đặc hiệu do virus\nmã hóa, chẳng hạn như reverse transcriptase (ở HIV), protease, hoặc DNA/RNA poly-\nmerase của virus. Nhờ đó, thuốc ngăn cản quá trình sao chép và nhân lên của virus.\nCác phương án còn lại không đúng vì:\nA sai. Enzyme của vi khuẩn là mục tiêu của thuốc kháng sinh, không phải thuốc kháng\nvirus.\nB sai. Phiên mã và dịch mã trong tế bào chủ là quá trình sống cơ bản của sinh vật chủ,\nnếu ức chế sẽ gây độc cho cơ thể.\nD sai. Enzyme của tế bào chủ không phải là đích tác động chính của thuốc kháng virus."
