      "explanation": "Chọn đáp án B.\nTrong Phần 2, mẫu được xử lý bằng NaOH để loại bỏ ion Mg2+ dưới dạng kết tủa\nMg(OH)2:\nMg2+(aq) + 2OH−(aq) → Mg(OH)2(r)\nSau khi tách kết tủa, ion Mg2+ đã bị loại bỏ khỏi dung dịch.\nCa2+ không kết tủa (hoặc vẫn còn trong dung dịch) và có khả năng phản ứng với EDTA.\nQuá trình chuẩn độ EDTA trong Phần 2 sẽ chỉ phản ứng với các ion kim loại hóa trị 2\ncòn lại, mà ở đây chính là Ca2+.\n\n\nCa2+(aq) + EDTA2−(aq) → Ca(EDTA)(aq)"
