      "section": "science",
      "sectionName": "Tư duy Khoa học & Giải quyết vấn đề (300đ)",
      "passage": "Dựa vào thông tin dưới đây để trả lời các câu từ 193 đến 195:\nMột nhà máy muốn xác định tổng độ cứng và nồng độ ion Mg2+ của mẫu nước khoáng. Kỹ sư cho 50\nmL nước khoáng cho vào bình định mức 100 mL, thêm nước cất đến vạch định mức thì thu được 100\nmL dung dịch X.\nPhần 1: Lấy 20 mL dung dịch X chuẩn độ với dung dịch EDTA 0,01 M, thì dùng hết 1,85 mL dung\ndịch EDTA.\nPhần 2: Lấy 20 mL dung dịch X, điều chỉnh pH của dung dịch bằng cách thêm NaOH 0,2 M sao cho\nCa2+ không kết tủa nhưng có thể loại ion Mg2+ dưới dạng kết tủa Mg(OH)2. Sau khi tách kết tủa,\ncũng tiến hành chuẩn độ với dung dịch EDTA 0,01 M thì thấy dùng hết 1,24 mL dung dịch EDTA.\nPhương trình chuẩn độ xảy ra như sau:\nMg2+(aq) + EDTA2−(aq) → Mg(EDTA)(aq)\nCa2+(aq) + EDTA2−(aq) → Ca(EDTA) (aq)",
      "clusterId": "kscl_science_c193",
      "question": "Nồng độ Mg2+ (ppm) trong mẫu nước khoáng ban đầu là bao nhiêu? Biết 1 ppm là 1 mg chất tan trong 1 L dung dịch.",
