      "passage": "Dựa vào thông tin dưới đây để trả lời các câu từ 196 đến 198:\nCon quay hồi chuyển (gyroscope) là thiết bị gồm một vật rắn quay nhanh quanh trục cố định, có khả\nnăng giữ ổn định hướng quay trong không gian nhờ định luật bảo toàn mômen động lượng.\nKhi một vật quay, nó có mômen động lượng L = Iω, trong đó I là mômen quán tính và ω là vectơ\nvận tốc góc.\nNếu không có mômen ngoại lực tác dụng, vectơ L sẽ giữ nguyên hướng và độ lớn không đổi, nghĩa là\ntrục quay của con quay không tự đổi hướng.\nKhi có mômen ngoại lực (ví dụ trọng lực) tác dụng vuông góc với L, trục quay của con quay không\nđổ ngã ngay, mà chuyển động chậm quanh phương thẳng đứng – hiện tượng này gọi là tiền tiến\n(precession).\nCon quay hồi chuyển được ứng dụng rộng rãi trong hệ thống định hướng của tàu vũ trụ, máy bay, tàu\nngầm, điện thoại thông minh và robot tự cân bằng.\nMômen động lượng của con quay có độ lớn: L = Iω\nvà mômen lực gây ra tốc độ tiền tiến được xác định bởi: M = LΩ\nvới Ω là tốc độ góc của chuyển động tiền tiến.",
