      "sectionName": "Tư duy Khoa học & Giải quyết vấn đề (300đ)",
      "passage": "Dựa vào thông tin dưới đây để trả lời các câu từ 202 đến 204:\n“Đại hội đại biểu toàn quốc lần thứ VI của Đảng đánh dấu mốc quan trọng trong lịch sử cách mạng\nViệt Nam với việc quyết định tiến hành công cuộc đổi mới toàn diện, đưa đất nước thoát khỏi tình\ntrạng khủng hoảng kinh tế - xã hội. Đường lối đổi mới được đưa ra tại Đại hội VI của Đảng trước hết\nlà đổi mới về tư duy nhận thức và tư tưởng, lý luận. Đảng ta nhấn mạnh: Muốn đổi mới tư duy, Đảng\nta phải nắm vững bản chất cách mạng và khoa học của chủ nghĩa Mác - Lê-nin, kế thừa di sản quý\nbáu về tư tưởng và lý luận cách mạng của Chủ tịch Hồ Chí Minh”.\n(Văn kiện Đảng toàn tập, Nxb. Chính trị quốc gia Sự thật, Hà Nội, 2006, t. 47, tr. 807)",
      "clusterId": "kscl_science_c202",
      "question": "Chiến lược kết hợp giữa Chủ nghĩa Mác - Lê-nin và Tư tưởng Hồ Chí theo tinh thần Đại hội VI nhằm tạo ra bản lề để Đảng Cộng sản Việt Nam có thể đồng thời dung hòa thành công cặp mâu thuẫn trung tâm nào trong công cuộc Đổi mới?",
      "options": [
        "A. Giữa yêu cầu mở cửa hội nhập kinh tế tối đa với yêu cầu ngăn chặn hoàn toàn các ảnh hưởng văn hóa tư bản.",
        "B. Giữa nhu cầu phá bỏ triệt để mô hình kế hoạch hóa tập trung với đòi hỏi phải bảo vệ tuyệt đối kinh tế quốc doanh và sở hữu toàn dân.",
        "C. Giữa sự cần thiết phải đổi mới, thay đổi căn bản để thoát khỏi khủng hoảng và sự kiên định, giữ vững định hướng chính trị xã hội chủ nghĩa.",
        "D. Giữa việc huy động tối đa nguồn vốn từ nước ngoài với việc giảm thiểu sự phụ thuộc vào các tổ chức tài chính quốc tế."
      ],
      "correctAnswer": 2,
      "explanation": "Chọn C\n* Bối cảnh Đại hội VI (1986)\nĐất nước ta trước Đại hội VI đang rơi vào khủng hoảng kinh tế - xã hội trầm trọng: lạm\nphát cao, sản xuất đình trệ, đời sống nhân dân khó khăn.\nTrong bối cảnh đó, Đảng nhận thấy cần phải đổi mới tư duy, đổi mới cơ chế kinh tế và\nphương thức lãnh đạo, nhưng không thể từ bỏ mục tiêu xã hội chủ nghĩa – nền tảng tư\ntưởng của Đảng và con đường cách mạng Việt Nam.\n* Vai trò của sự kết hợp giữa Chủ nghĩa Mác – Lê-nin và Tư tưởng Hồ Chí Minh\nChủ nghĩa Mác – Lê-nin cung cấp cho Đảng cơ sở lý luận khoa học và phương pháp\nbiện chứng, giúp nhận thức rõ quy luật vận động, biến đổi của xã hội.\nTư tưởng Hồ Chí Minh bổ sung tính sáng tạo, thực tiễn, linh hoạt, coi trọng “lấy dân\nlàm gốc”, “vì lợi ích của dân mà đổi mới”.\nSự kết hợp này giúp Đảng:\nGiữ vững bản chất cách mạng và khoa học của CNXH,\nĐồng thời vận dụng linh hoạt, sáng tạo để phù hợp với điều kiện cụ thể của Việt Nam\ntrong thời kỳ mới.\n* Cặp mâu thuẫn trung tâm mà Đảng cần dung hòa: Đó là mâu thuẫn giữa “đổi mới\n– thay đổi căn bản để phát triển” và “kiên định định hướng chính trị – giữ vững con\nđường XHCN”.\nNếu chỉ tập trung vào đổi mới mà buông lỏng định hướng XHCN → có nguy cơ chệch\nhướng, sa vào con đường tư bản.\n\n\nNếu chỉ giữ định hướng chính trị cứng nhắc, không đổi mới → sẽ bảo thủ, trì trệ, tiếp\ntục khủng hoảng.\nChính sự kết hợp nhuần nhuyễn giữa lý luận Mác – Lê-nin và Tư tưởng Hồ Chí Minh\nđã giúp Đảng giải quyết mâu thuẫn này một cách biện chứng, mở ra con đường “Đổi\nmới toàn diện nhưng không đổi hướng”.\n+ A. Sai lệch: Đại hội VI không chủ trương “ngăn chặn hoàn toàn ảnh hưởng văn hóa tư\nbản”, mà chủ trương chủ động hội nhập có chọn lọc, “hòa nhập nhưng không hòa tan”.\n+ B. Sai: Đổi mới không phải là “phá bỏ triệt để” hay “bảo vệ tuyệt đối” một mô hình,\nmà là cải cách cơ chế quản lý kinh tế, kết hợp nhiều thành phần kinh tế.\n+ D. Chỉ phản ánh một khía cạnh kinh tế đối ngoại, không phải cặp mâu thuẫn trung\ntâm mang tính chiến lược – tư tưởng của toàn bộ công cuộc Đổi mới."
