      "clusterId": "kscl_science_c226",
      "question": "Xét các phát biểu sau về động cơ điện: (1) Lực từ tác dụng mạnh nhất khi dây dẫn song song với đường sức từ. (2) Mômen quay khung dây trong động cơ điện sinh ra do hai lực từ song song, ngược chiều nhau. (3) Cổ góp trong động cơ điện có tác dụng đổi chiều dòng điện trong cuộn dây quay. (4) Khi đảo chiều dòng điện vào cuộn dây, chiều quay của động cơ có thể thay đổi. Có bao nhiêu phát biểu đúng?",
