      "passage": "Dựa vào thông tin dưới đây để trả lời các câu từ 262 đến 264:\nÝ tưởng về một ASEAN bao gồm 10 quốc gia Đông Nam Á trở thành hiện thực vào những năm cuối\ncủa thập niên 90 trong thế kỷ XX, đưa đến những thay đổi căn bản về Hiệp hội cũng như đối với tình\nhình khu vực. ASEAN-10 đã giúp chấm dứt sự chia rẽ và đối đầu giữa các nước Đông Nam Á; tạo\ndựng mối quan hệ mới về chất giữa các nước thành viên, trên cơ sở hữu nghị, hiểu biết và tin cậy lẫn\nnhau, hợp tác toàn diện và ngày càng chặt chẽ cả về song phương, đa phương.\nĐoàn kết và hợp tác ASEAN ngày càng được củng cố, tăng cường theo phương châm bảo đảm sự\n“thống nhất trong đa dạng”, trên cơ sở các mục tiêu, nguyên tắc cơ bản của Hiệp hội. ASEAN-10 đã\nđưa Hiệp hội trở thành một tổ chức hợp tác khu vực thực sự, mang tính toàn diện và năng động hơn;\nđồng thời, là nhân tố quan trọng bảo đảm hòa bình, an ninh, hợp tác, phát triển ở Đông Nam Á và khu\nvực châu Á - Thái Bình Dương. ASEAN cũng dần hình thành cách tiếp cận và phương thức giải quyết\nriêng đối với những vấn đề của khu vực và quốc tế, đó là “Phương cách ASEAN”, chú trọng đối thoại\nvà hợp tác, năng động và linh hoạt để tìm được tiếng nói chung và đồng thuận.\n(Nguồn https://www.tapchicongsan.org.vn/)",
