      "explanation": "Chọn D\n“Phương cách ASEAN” là phong cách ứng xử đặc trưng trong quan hệ giữa các quốc\ngia thành viên và giữa ASEAN với các đối tác quốc tế. Được hình thành và củng cố qua\nnhiều thập niên, phương cách này dựa trên các nguyên tắc nền tảng như:\n+ Tôn trọng độc lập, chủ quyền và toàn vẹn lãnh thổ của các quốc gia.\n+ Không can thiệp vào công việc nội bộ của nhau.\n+ Giải quyết tranh chấp bằng biện pháp hòa bình, thông qua đối thoại và đồng thuận.\n+ Đề cao hợp tác, hữu nghị, tránh đối đầu và xung đột.\n* Tầm vóc và ý nghĩa chiến lược của “Phương cách ASEAN”:\nTrong bối cảnh Đông Nam Á nằm giữa các khu vực chiến lược và cạnh tranh của các\ncường quốc (Mỹ, Trung Quốc, Nhật Bản, Nga, Ấn Độ.), “Phương cách ASEAN” đã:\n+ Giúp ASEAN duy trì đoàn kết nội khối, dù các nước có chế độ chính trị, trình độ phát\ntriển, lợi ích khác nhau.\n+ Tạo ra bản sắc riêng – một mô hình hợp tác khu vực “mềm dẻo, linh hoạt, dựa trên\nđồng thuận”, được quốc tế công nhận.\n+ Khẳng định vai trò trung gian, cầu nối và điều phối đối thoại khu vực.\n+ Giúp các cường quốc chấp nhận và tôn trọng vai trò “trung tâm” của ASEAN trong\ncấu trúc an ninh – chính trị châu Á – Thái Bình Dương.\n→ Vì thế, “Phương cách ASEAN” không chỉ là một nguyên tắc ứng xử, mà còn là một\nchiến lược giúp ASEAN tồn tại, phát triển, và giữ thế cân bằng trong môi trường cạnh\ntranh toàn cầu.\n- A. Sai. ASEAN không có thẩm quyền “trọng tài bắt buộc” đối với các tranh chấp quốc\ntế; khối chỉ đóng vai trò trung gian hòa giải tự nguyện, không mang tính cưỡng chế.\n- B. Sai. ASEAN không phải là một khối quân sự, và “Phương cách ASEAN” càng chủ\n\n\ntrương hòa bình, đối thoại, không đối đầu vũ trang.\n- C. Sai. ASEAN chủ trương mở cửa, hợp tác với các đối tác bên ngoài thông qua các\ncơ chế như ASEAN+3, ARF, EAS. . . , chứ không theo đuổi chính sách “độc lập tuyệt\nđối” về kinh tế.\nChọn đáp án D . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . □\nDựa vào thông tin dưới đây để trả lời các câu hỏi từ 265 đến 267:\nTheo số liệu của Cơ quan Di trú Anh, số đơn xin định cư của công dân Mỹ năm 2025 tăng gần 40%\nso với năm trước – mức cao nhất trong vòng hai thập kỷ. Các chuyên gia cho rằng hiện tượng “di cư\nngược” cho thấy: “Giấc mơ Mỹ” không còn là điểm đến duy nhất cho khát vọng thịnh vượng. Ngược\nlại, Vương quốc Anh với nền giáo dục, y tế công cộng và mức độ an toàn cao đang trở thành “miền\nđất hứa” mới của nhiều người Mỹ.\nNguyên nhân đến từ sự kết hợp của nhiều yếu tố: chi phí sinh hoạt và y tế tại Mỹ tăng nhanh, bất ổn\nchính trị kéo dài, trong khi Anh lại thu hút với chính sách thị thực linh hoạt, phúc lợi xã hội và môi\ntrường sống an toàn. Nhiều người Mỹ thuộc tầng lớp trung lưu và giới chuyên môn cao chọn các thành"
