      "passage": "Dựa vào thông tin dưới đây để trả lời các câu từ 283 đến 285:\nMột nhà nghiên cứu tiến hành khảo sát ảnh hưởng của ethylene glycol (C2H6O2) – một chất lỏng\nkhông màu, không mùi, tan vô hạn trong nước – lên điểm đông đặc của nước. Đây là nguyên lý cơ\nbản được ứng dụng trong sản xuất nước làm mát (chống đông) cho động cơ ô tô.\nThí nghiệm được tiến hành bằng cách hòa tan 100 g ethylene glycol vào 400 g nước cất. Hỗn hợp được\nkhuấy đều và làm lạnh chậm để xác định nhiệt độ bắt đầu xuất hiện tinh thể rắn.\nBiết, Công thức tính độ hạ điểm đông: ∆Tf = Kf · m · i\nTrong đó:\nm là nồng độ molan (mol/kg dung môi), i là hệ số Van’t Hoff (số tiểu phân tách ra từ một phân tử\nchất tan).\nHằng số nghiệm lạnh của nước: Kf = 1,86 ◦C · kg/mol.\nEthylene glycol là chất không điện li, không bay hơi.\nKhối lượng mol của ethylene glycol: M ≈ 62,07 g/mol.\nCho các yếu tố sau:\n(1) Khối lượng của dung môi (nước).\n(2) Áp suất khí quyển tại phòng thí nghiệm.\n(3) Khối lượng của chất tan (ethylene glycol).\n(4) Bản chất (công thức hóa học) của chất tan để xác định hệ số Van’t Hoff (i).\n(5) Thể tích của dung dịch sau khi hòa tan.",
      "clusterId": "kscl_science_c283",
      "question": "Để độ hạ điểm đông ∆Tf của dung dịch được xác định chính xác nhất trong thí nghiệm này, nhà nghiên cứu cần kiểm soát hoặc đo lường chính xác những yếu tố nào sau đây? (Chọn tất cả các phương án đúng)",
